<script setup lang="ts">import type { MasonryLayoutDetail } from '@fex-design/vue/primitive/masonry';import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/vue/primitive/masonry';import { ref } from 'vue';import { masonryItems } from './data';const items=masonryItems.slice(0,9),ordered=ref<Record<string,number>>({}),shortest=ref<Record<string,number>>({});const cols=(value:MasonryLayoutDetail)=>Object.fromEntries(value.items.map(item=>[String(item.key),item.column+1]))</script>
<template><div class="grid gap-space-xl"><section v-for="placement in ['ordered','shortest'] as const" :key="placement" class="grid gap-space-sm"><div><h3 class="font-medium">{{placement==='ordered'?'按输入顺序（ordered）':'按当前最短列（shortest）'}}</h3><p class="text-sm text-muted-foreground">{{placement==='ordered'?'按第 1、2、3 列循环分配，视觉读取顺序更稳定。':'每次进入累计高度最小的列，列高更均衡。'}}</p></div><MasonryRoot :columns="3" :gap="12" :placement="placement" :on-layout-change="value=>placement==='ordered'?ordered=cols(value):shortest=cols(value)"><MasonryViewport><MasonryItem v-for="(item,index) in items" :key="item.id" :item-key="item.id" :index="index"><div class="rounded-md border border-border bg-muted-background p-space-sm" :style="{height:`${item.height/2}px`}"><strong>Card {{index+1}}</strong><p class="text-xs text-muted-foreground">输入序号 {{index+1}} · 最终第 {{(placement==='ordered'?ordered:shortest)[item.id]??'…'}} 列</p></div></MasonryItem></MasonryViewport></MasonryRoot></section><section class="grid gap-space-sm"><h3 class="font-medium">指定列与自动分配混排</h3><MasonryRoot :columns="{minColumnWidth:160,max:3}" :gap="12"><MasonryViewport><MasonryItem v-for="(item,index) in items.slice(0,6)" :key="item.id" :item-key="item.id" :index="index" :column="index===1?2:undefined"><div class="rounded-md border border-border bg-muted-background p-space-sm" :style="{height:`${item.height/2}px`}">Card {{index+1}} · {{index===1?'固定第 3 列':'自动最短列'}}</div></MasonryItem></MasonryViewport></MasonryRoot></section></div></template>
